// Simple XML/HTML mode for CodeMirror 5
CodeMirror.defineMode("xml", function(config, parserConfig) {
  var indentUnit = config.indentUnit;
  var multilineTagIndentFactor = parserConfig.multilineTagIndentFactor || 1;
  var multilineTagIndentPastTag = parserConfig.multilineTagIndentPastTag;
  if (multilineTagIndentPastTag == null) multilineTagIndentPastTag = true;

  var Kludges = parserConfig.htmlMode ? {
    autoSelfClosers: {'area': true, 'base': true, 'br': true, 'col': true, 'command': true,
                      'embed': true, 'frame': true, 'hr': true, 'img': true, 'input': true,
                      'keygen': true, 'link': true, 'meta': true, 'param': true, 'source': true,
                      'track': true, 'wbr': true, 'menuitem': true},
    implicitlyClosed: {'dd': true, 'li': true, 'optgroup': true, 'option': true, 'p': true,
                       'rp': true, 'rt': true, 'tbody': true, 'td': true, 'tfoot': true,
                       'th': true, 'tr': true},
    contextGrabbers: {
      'dd': {'dd': true},
      'dt': {'dd': true, 'dt': true},
      'li': {'li': true},
      'option': {'option': true, 'optgroup': true},
      'optgroup': {'optgroup': true},
      'p': {'address': true, 'article': true, 'aside': true, 'blockquote': true, 'dir': true,
            'div': true, 'dl': true, 'fieldset': true, 'footer': true, 'form': true,
            'h1': true, 'h2': true, 'h3': true, 'h4': true, 'h5': true, 'h6': true,
            'header': true, 'hgroup': true, 'hr': true, 'menu': true, 'nav': true, 'ol': true,
            'p': true, 'pre': true, 'section': true, 'table': true, 'ul': true},
      'rp': {'rp': true, 'rt': true},
      'rt': {'rp': true, 'rt': true},
      'tbody': {'tbody': true, 'tfoot': true},
      'td': {'td': true, 'th': true},
      'tfoot': {'tbody': true},
      'th': {'td': true, 'th': true},
      'thead': {'tbody': true, 'tfoot': true},
      'tr': {'tr': true}
    },
    doNotIndent: {"pre": true},
    allowUnquoted: true,
    allowMissing: true,
    caseFold: true
  } : {autoSelfClosers: {}, implicitlyClosed: {}, contextGrabbers: {}, doNotIndent: {}, allowUnquoted: false, allowMissing: false, caseFold: false};

  var style = parserConfig.htmlMode ? htmlStyle : xmlStyle;

  var Kludge = Kludges;
  var top = [];

  function xmlStyle(tagName, state) {
    var type = state.type;
    if ((type == "openTag" || type == "closeTag") && Kludge.caseFold) tagName = tagName.toLowerCase();
    if (type == "openTag") {
      if (tagName == "script") return "js";
      if (Kludge.doNotIndent.hasOwnProperty(tagName)) return "xml" + tagName;
    }
    if (type == "closeTag" && Kludge.doNotIndent.hasOwnProperty(tagName)) return "xml" + tagName;
    return "xml" + type;
  }

  function htmlStyle(tagName, state) {
    var type = state.type;
    if ((type == "openTag" || type == "closeTag") && Kludge.caseFold) tagName = tagName.toLowerCase();
    if (type == "openTag") {
      if (tagName == "script") return "js";
      if (tagName == "style") return "css";
      if (Kludge.doNotIndent.hasOwnProperty(tagName)) return "html" + tagName;
    }
    if (type == "closeTag" && Kludge.doNotIndent.hasOwnProperty(tagName)) return "html" + tagName;
    return "html" + type;
  }

  function readTagName(stream, startOfTag) {
    var tagName = "";
    while (!stream.eol()) {
      var ch = stream.next();
      if (!/[A-Za-z0-9\-_]/.test(ch)) {
        stream.backUp(1);
        break;
      }
      tagName += ch;
    }
    return tagName;
  }

  function readAttributeName(stream) {
    var attrName = "";
    while (!stream.eol()) {
      var ch = stream.peek();
      if (!/[A-Za-z0-9\-_]/.test(ch)) break;
      stream.next();
      attrName += ch;
    }
    return attrName;
  }

  function readAttributeValue(stream, quote) {
    var value = "";
    var escaped = false;
    while (!stream.eol()) {
      var ch = stream.next();
      if (escaped) {
        value += ch;
        escaped = false;
      } else if (ch == quote) {
        break;
      } else if (ch == "\\") {
        value += ch;
        escaped = true;
      } else {
        value += ch;
      }
    }
    return value;
  }

  return {
    startState: function() {
      return {tokenize: baseState, type: null, indentation: 0, stack: []};
    },

    token: function(stream, state) {
      state.tokenize(stream, state);
      return style(state.type, state);
    },

    indent: function(state, textAfter) {
      if (state.tokenize == baseState && /^<\//.test(textAfter))
        return state.indentation;
      else
        return state.indentation + indentUnit;
    },

    electricInput: /<\/[\s\S]*?>/,
    blockCommentStart: "<!--",
    blockCommentEnd: "-->",
    lineComment: null
  };

  function baseState(stream, state) {
    if (stream.eatSpace()) return null;
    if (stream.match(/^<!--/)) {
      state.tokenize = commentState;
      return state.tokenize(stream, state);
    }
    if (stream.match(/^(<!\[CDATA\[)/)) {
      state.tokenize = cdataState;
      return state.tokenize(stream, state);
    }
    if (stream.match(/^<\//)) {
      state.tokenize = closeTagState;
      return state.tokenize(stream, state);
    }
    if (stream.match(/^</)) {
      state.tokenize = openTagState;
      return state.tokenize(stream, state);
    }
    if (stream.match(/^&/)) {
      state.tokenize = entityState;
      return state.tokenize(stream, state);
    }
    state.tokenize = textState;
    return state.tokenize(stream, state);
  }

  function textState(stream, state) {
    var ch = stream.next();
    if (ch == "<") {
      stream.backUp(1);
      state.tokenize = baseState;
      return null;
    }
    if (ch == "&") {
      stream.backUp(1);
      state.tokenize = entityState;
      return null;
    }
    return null;
  }

  function commentState(stream, state) {
    while (!stream.eol()) {
      if (stream.match(/-->/)) {
        state.tokenize = baseState;
        break;
      }
      stream.next();
    }
    return "comment";
  }

  function cdataState(stream, state) {
    while (!stream.eol()) {
      if (stream.match(/\]\]>/)) {
        state.tokenize = baseState;
        break;
      }
      stream.next();
    }
    return "comment";
  }

  function entityState(stream, state) {
    var ch;
    while ((ch = stream.next()) != null) {
      if (ch == ";") break;
      if (!/[a-zA-Z0-9#]/.test(ch)) break;
    }
    state.tokenize = baseState;
    return "atom";
  }

  function openTagState(stream, state) {
    if (stream.match(/^[\s\u00a0]*/)) return null;
    var tagName = readTagName(stream, true);
    if (!tagName) return "error";
    state.type = "openTag";
    state.tokenize = inTagState;
    return "tag";
  }

  function closeTagState(stream, state) {
    var tagName = readTagName(stream, false);
    state.type = "closeTag";
    state.tokenize = baseState;
    return "tag";
  }

  function inTagState(stream, state) {
    if (stream.match(/^[\s\u00a0]*/)) return null;
    if (stream.match(/^\/?>/)) {
      state.tokenize = baseState;
      return "tag";
    }
    var attrName = readAttributeName(stream);
    if (!attrName) return "error";
    state.type = "attribute";
    if (stream.eat(/^\s*=\s*/)) {
      state.type = "attribute";
      if (stream.match(/^["']/)) {
        state.tokenize = inAttributeValueState(stream.current());
        return state.type;
      }
      state.tokenize = inUnquotedAttributeValueState;
      return state.type;
    }
    return state.type;
  }

  function inAttributeValueState(quote) {
    return function(stream, state) {
      readAttributeValue(stream, quote);
      state.tokenize = inTagState;
      return "string";
    };
  }

  function inUnquotedAttributeValueState(stream, state) {
    while (!stream.eol()) {
      var ch = stream.peek();
      if (ch == ">" || /\s/.test(ch)) break;
      stream.next();
    }
    state.tokenize = inTagState;
    return "string";
  }
});

CodeMirror.defineMIME("text/xml", "xml");
CodeMirror.defineMIME("application/xml", "xml");
CodeMirror.defineMIME("text/html", {name: "xml", htmlMode: true});
CodeMirror.defineMIME("text/xhtml", {name: "xml", htmlMode: true});